#!/bin/sh
set -eu
# Native UI supplement: restore a target directory from the immutable sibling baseline.
if [ -d "$1" ]; then
  root=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
  baseline="$root/implementation/BASELINE_LATEST"
  [ -d "$baseline" ] || baseline="$root/implementation/BASELINE"
  [ -d "$baseline" ] || { printf '%s\n' 'Missing sibling native baseline' >&2; exit 3; }
  cp -R "$baseline/." "$1/"
  printf '%s\n' 'ROLLBACK restored pristine native UI source and payload from sibling baseline'
  exit 0
fi
[ "$#" -eq 1 ] || { printf "%s\n" "Usage: ROLLBACK.sh TARGET_COPY" >&2; exit 2; }
case "$1" in -*) printf "%s\n" "Use an absolute path or ./TARGET_COPY" >&2; exit 2;; esac
base64 -d > "$1" <<'IVAN_PRISTINE'

IVAN_PRISTINE
printf "%s\n" "ROLLBACK restored pristine UI preview HTML"
